package br.com.lealinfo.vidraceiro;
import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Individual access. UI leases expire offline; every server operation independently revalidates the session. */
final class AccessControl {
 static volatile String token="";static volatile JSONObject user;static volatile long checked;static AccessControl active;
 final MainActivity a;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService work=Executors.newSingleThreadExecutor();int generation;boolean closed;
 static final String[] KEYS={"create","send","images","history","reports","finance","edit","customers","suppliers","materials","cut","drawing","documents","calculator"};
 static final String[] LABELS={"Criar orçamentos","Enviar ao PDV","Criar imagem","Histórico","Relatórios / autoria","Financeiro (conforme módulo disponível)","Editar orçamentos recebidos","Clientes","Fornecedores","Materiais","Plano de corte","Projetos 3D","Contratos / documentos","Calculadora"};
 AccessControl(MainActivity a){this.a=a;active=this;token="";user=null;checked=0;try{String saved=a.getSharedPreferences("access37",0).getString("session","");if(!saved.isEmpty())token=LocalVault.decode(android.util.Base64.decode(saved,2));}catch(Exception e){clear();}if(!token.isEmpty())refresh();main.postDelayed(poll,15000);}
 static boolean ready(){return user!=null&&!token.isEmpty()&&SystemClock.elapsedRealtime()-checked<25000;}
 static boolean owner(){return ready()&&"owner".equals(user.optString("role"));}
 static boolean can(String p){if(!ready())return false;if(owner())return true;JSONArray x=user.optJSONArray("permissions");for(int i=0;x!=null&&i<x.length();i++)if(p.equals(x.optString(i)))return true;return false;}
 static JSONObject author(){JSONObject o=new JSONObject();try{if(ready())for(String k:new String[]{"uid","matricula","name"})o.put(k,user.optString(k));}catch(Exception ignored){}return o;}
 static boolean visible(JSONObject p){JSONObject author=p==null?null:p.optJSONObject("authorship");return ready()&&(owner()||can("history")||(author!=null&&author.optString("uid").equals(user.optString("uid"))));}
 static void require(String permission)throws Exception{if(!can(permission))throw new Exception("Acesso não autorizado ou sessão sem confirmação. Entre novamente.");}
 static void denied(){AccessControl x=active;if(x!=null)x.main.post(()->{x.clear();x.show();});}
 void clear(){generation++;token="";user=null;checked=0;a.getSharedPreferences("access37",0).edit().remove("session").apply();a.saveScreen=null;a.current=null;}
 interface Result{void done(JSONObject r)throws Exception;}
 void call(String action,JSONObject body,Result done){int g=generation;work.execute(()->{try{JSONObject r=SyncTransport.request("/sync/access/"+action,body);main.post(()->{if(closed||g!=generation)return;try{done.done(r);}catch(Exception e){a.message(e.getMessage());}});}catch(Exception e){main.post(()->{if(!closed&&g==generation)a.message(e.getMessage());});}});}
 void enter(JSONObject r)throws Exception{token=r.getString("session");user=r.getJSONObject("user");checked=SystemClock.elapsedRealtime();a.getSharedPreferences("access37",0).edit().putString("session",android.util.Base64.encodeToString(LocalVault.encode(token),2)).apply();a.current=null;a.saveScreen=null;a.home();if(a.sync!=null)a.sync.tick();}
 void refresh(){if(token.isEmpty())return;call("me",new JSONObject(),r->{user=r.getJSONObject("user");checked=SystemClock.elapsedRealtime();if("access".equals(a.page))a.home();});}
 final Runnable poll=new Runnable(){public void run(){if(closed)return;if(!token.isEmpty())refresh();if(user!=null&&!ready()){user=null;a.saveScreen=null;a.current=null;show();}main.postDelayed(this,15000);}};
 EditText field(String caption,boolean password){EditText e=a.input(caption,"",false);if(password)e.setInputType(129);return e;}
 void show(){a.screen("access","ACESSO INDIVIDUAL");a.note("ANGRA VIDROS • QA37\nConecte este aparelho ao PDV e use sua matrícula pessoal. A matrícula do proprietário é PROPRIETARIO.");EditText id=field("Matrícula",false),pw=field("Senha",true);a.button("ENTRAR",()->call("login",new JSONObject().put("matricula",a.val(id)).put("password",pw.getText().toString()),this::enter));a.button("PRIMEIRO ACESSO / ATIVAR",this::activate);a.button("AUTORIZAR PRIMEIRO PROPRIETÁRIO",()->call("bootstrap",new JSONObject(),r->{String url=r.getString("authorizationUrl");a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}));a.button("CONECTAR ESTE APARELHO AO PDV",a::integration);}
 void activate(){a.screen("access","ATIVAR ACESSO");a.note("Funcionário: informe matrícula e código fornecidos pelo proprietário. Proprietário: autorize este aparelho primeiro e deixe o código vazio. Crie sua própria senha de pelo menos 8 caracteres.");EditText id=field("Matrícula",false),code=field("Código de ativação",false),pw=field("Sua nova senha",true),confirm=field("Confirme a senha",true);a.button("ATIVAR",()->{if(!pw.getText().toString().equals(confirm.getText().toString()))throw new Exception("As senhas não coincidem.");call("activate",new JSONObject().put("matricula",a.val(id)).put("code",a.val(code)).put("password",pw.getText().toString()),this::enter);});a.button("VOLTAR",this::show);}
 void manage(){if(!owner()){a.message("Somente o proprietário administra funcionários.");return;}call("users",new JSONObject(),r->{a.screen("accessAdmin","GERENCIAR FUNCIONÁRIOS");a.button("CADASTRAR FUNCIONÁRIO",()->form(null));JSONArray list=r.getJSONArray("users");for(int i=0;i<list.length();i++){JSONObject u=list.getJSONObject(i);a.button(u.optString("matricula")+" • "+u.optString("name")+" • "+u.optString("status"),()->details(u));}a.button("AUDITORIA DE ACESSO",()->call("audit",new JSONObject(),x->{a.screen("accessAdmin","AUDITORIA");JSONArray log=x.getJSONArray("audit");for(int i=log.length()-1;i>=0;i--){JSONObject item=log.getJSONObject(i);a.note(new java.util.Date(item.optLong("at"))+" • "+item.optString("action")+" • "+item.optString("target"));}a.button("VOLTAR",this::manage);}));a.button("INÍCIO",a::home);});}
 void result(JSONObject r)throws Exception{if(r.has("activationCode"))a.message("Entregue este código somente à pessoa cadastrada. Válido por 24 horas, uso único.\nMatrícula: "+r.optString("matricula")+"\n\n"+r.getString("activationCode"));manage();}
 void update(JSONObject u,String op)throws Exception{call("update",new JSONObject().put("matricula",u.getString("matricula")).put("operation",op),this::result);}
 void details(JSONObject u){if(!owner())return;a.screen("accessAdmin",u.optString("name"));a.note("Matrícula fixa: "+u.optString("matricula")+"\nPerfil: "+u.optString("role")+" • "+u.optString("status"));if(!"owner".equals(u.optString("role"))&&!"deleted".equals(u.optString("status"))){a.button("PERMISSÕES INDIVIDUAIS",()->form(u));a.button("BLOQUEAR",()->update(u,"block"));a.button("DESBLOQUEAR",()->update(u,"unblock"));a.button("REEMITIR ATIVAÇÃO / REVOGAR SENHA",()->new InteriorVisuals.Dialog(a).setMessage("Revogar todos os acessos e emitir nova ativação para esta pessoa?").setPositiveButton("CONFIRMAR",(d,w)->a.run(()->update(u,"activation"))).setNegativeButton("VOLTAR",null).show());a.button("EXCLUIR E REVOGAR CREDENCIAIS",()->new InteriorVisuals.Dialog(a).setMessage("Revogar acessos? A matrícula permanecerá reservada e o histórico comercial será preservado.").setPositiveButton("EXCLUIR",(d,w)->a.run(()->update(u,"delete"))).setNegativeButton("VOLTAR",null).show());}a.button("VOLTAR",this::manage);}
 void form(JSONObject u){if(!owner())return;a.screen("accessAdmin",u==null?"CADASTRAR FUNCIONÁRIO":"PERMISSÕES INDIVIDUAIS");EditText id=field("Matrícula fixa (não reutilizável)",false),name=field("Nome completo",false);if(u!=null){id.setText(u.optString("matricula"));name.setText(u.optString("name"));id.setEnabled(false);name.setEnabled(false);}CheckBox manager=new CheckBox(a);manager.setTextColor(MainActivity.TEXT);manager.setText("GERENTE • permissões personalizadas");manager.setChecked(u!=null&&"manager".equals(u.optString("role")));a.root.addView(manager);ArrayList<CheckBox> boxes=new ArrayList<>();for(int i=0;i<KEYS.length;i++){CheckBox b=new CheckBox(a);b.setTextColor(MainActivity.TEXT);b.setText(LABELS[i]);JSONArray ps=u==null?null:u.optJSONArray("permissions");for(int j=0;ps!=null&&j<ps.length();j++)if(KEYS[i].equals(ps.optString(j)))b.setChecked(true);boxes.add(b);a.root.addView(b);b.setEnabled(manager.isChecked());}manager.setOnCheckedChangeListener((v,on)->{for(CheckBox b:boxes)b.setEnabled(on);});a.note("Funcionário tem somente criação, imagem e envio. Apenas o proprietário administra acessos. Financeiro e estoque continuam sendo módulos oficiais do PDV.");a.button("SALVAR",()->{if(!owner())throw new Exception("Sessão administrativa encerrada.");JSONArray ps=new JSONArray();for(int i=0;i<boxes.size();i++)if(boxes.get(i).isChecked())ps.put(KEYS[i]);JSONObject body=new JSONObject().put("matricula",a.val(id)).put("role",manager.isChecked()?"manager":"employee").put("permissions",ps);if(u==null)body.put("name",a.val(name));else body.put("operation","permissions");call(u==null?"create":"update",body,this::result);});a.button("VOLTAR",this::manage);}
 void submissions(){call("submissions",new JSONObject(),r->{a.screen("accessReport","AUTORIA DOS ORÇAMENTOS");JSONArray rows=r.getJSONArray("submissions");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),by=row.optJSONObject("author");a.note(row.optString("title")+"\n"+(by==null?"Anterior ao controle individual":by.optString("matricula")+" • "+by.optString("name"))+"\n"+(row.optBoolean("receivedByPdv")?"Recebido no PDV":"Aguardando PDV"));}a.button("VOLTAR",a::home);});}
 void logout(){call("logout",new JSONObject(),r->{clear();show();});}
 void close(){closed=true;main.removeCallbacksAndMessages(null);work.shutdownNow();if(active==this)active=null;user=null;token="";checked=0;}
}
